// UML Representation:
// +-----------------------+
// |      BankAccount      |
// +-----------------------+
// | - accountNumber: string|
// | - balance: number     |
// | # interestRate: number|
// +-----------------------+
// | + deposit(amt: number)|
// | + withdraw(amt:number)|
// | + getBalance(): number|
// +-----------------------+

export class BankAccount {
  private accountNumber: string;
  private balance: number;
  protected interestRate: number;

  constructor(accNo: string, openingDeposit: number, rate = 0.05) {
    if (openingDeposit < 0) throw new Error('Initial deposit must be non-negative');
    this.accountNumber = accNo;
    this.balance = openingDeposit;
    this.interestRate = rate;
  }

  public deposit(amount: number): void {
    if (amount <= 0) throw new Error('Deposit must exceed zero');
    this.balance += amount;
  }

  public withdraw(amount: number): boolean {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  public getBalance(): number {
    return this.balance;
  }
}

// Interface Realization in TypeScript:
interface PaymentGateway {
  processPayment(amount: number, currency: string): Promise<boolean>;
  refund(transactionId: string): Promise<boolean>;
}

// Stereotype <<entity>>
export class Order {
  constructor(public orderId: string, public totalAmount: number) {}
}

// Association Class: Connects Student & Course with Grade metadata
export class Enrollment {
  constructor(
    public studentId: string,
    public courseCode: string,
    public enrollmentDate: Date,
    public currentGrade: number = 0
  ) {}

  public recordGrade(score: number): void {
    if (score < 0 || score > 100) throw new Error('Grade out of bounds');
    this.currentGrade = score;
  }
}
